const inputItems = $input.all();

// Robust extraction in case the HTTP node returns an array in different shapes
const rows = [];
for (const it of inputItems) {
  if (!it || it.json == null) continue;

  if (Array.isArray(it.json)) {
    for (const r of it.json) rows.push(r);
    continue;
  }

  if (it.json.body && Array.isArray(it.json.body)) {
    for (const r of it.json.body) rows.push(r);
    continue;
  }

  rows.push(it.json);
}

